sys_script_client.script:
function onLoad() {
    'use strict';

    // =================================================================
    // BLOCK 1 of 2 - PUT THE FORM BACK IN STEP WITH THE DATABASE AFTER
    // AN ABORTED SUBMIT. QA Issue 17, the FIELD VALUE half.
    //
    // THE DEFECT. On an Open case, set Status to Draft and press Update
    // once. ../business_rules/x_casemgmt_block_draft_backtransition.xml
    // refuses the write, the verbatim "Cases cannot be returned to
    // Draft." is displayed, and nothing is persisted - the list and a
    // fresh REST read both still say Open and sys_mod_count is
    // unchanged. But the platform re-renders an aborted submit with the
    // values that were POSTED, so the form still shows Status = "Draft"
    // until the user reloads: what is displayed and what is stored
    // diverge, on the one field the whole state machine turns on.
    //
    // THE MECHANISM. The client cannot see the stored value on its own,
    // so it is supplied through the platform's own channel: the display
    // Business Rule
    // ../business_rules/x_casemgmt_case_display_stored_state.xml
    // re-reads the row from the database by its own sys_id with a fresh
    // GlideRecord and publishes the result as
    // g_scratchpad.x_casemgmt_stored_status. That rule never reads a
    // status off `current`, because it is NOT established whether a
    // display rule is handed the stored or the posted record on an abort
    // re-render - see its header. This block reads that one string and
    // corrects the control when, and only when, the two disagree.
    //
    // FAIL SAFE, DELIBERATELY. Every uncertain path is a silent no-op
    // that changes nothing: no scratchpad (no display rule ran), an
    // empty or absent value (the rule could not prove a stored status),
    // a value this application does not recognise, `status` not on the
    // form, the two values already equal, or any exception at all. The
    // block only ever writes a value the server demonstrated against a
    // fresh database read, so it cannot invent a state and cannot fight
    // a user who is legitimately editing the field.
    //
    // IT CLEARS NO MESSAGE, AND MUST NOT. AAP Section 0.5.5 requires the
    // blocking error to be surfaced on the form, so the banner from the
    // aborted save has to survive this correction. g_form.setValue()
    // does not touch the message area; nothing here calls
    // g_form.clearMessages(), addErrorMessage(), addInfoMessage() or
    // reloads the form, and nothing may be added that does.
    //   One interaction was traced and is worth knowing about:
    //   ./x_casemgmt_case_flush_stale_messages.xml (order 100, so its
    //   listeners are already bound when this script runs at order 200)
    //   registers native "input"/"change" listeners on the four
    //   mandatory controls - `status` among them - that call
    //   g_form.clearMessages(). Per the DOM specification a programmatic
    //   value assignment fires neither event, and jQuery's
    //   trigger('change') does not reach addEventListener handlers, so
    //   setValue() here is not expected to trip them and the banner is
    //   expected to stand. That expectation is stated, not assumed
    //   proven: it is a runtime observation, and if a release ever did
    //   dispatch a trusted-looking change event the remedy belongs in
    //   that script (ignore events whose isTrusted is false), not here,
    //   because suppressing or re-writing a message from this block is
    //   forbidden either way.
    //
    // WHY THIS BLOCK RUNS FIRST. Three reasons, all about the terminal
    // lockdown in BLOCK 2 reading a status it can trust: (1) BLOCK 2
    // early-returns unless status is Closed, so on a Closed case whose
    // posted status was something else the lockdown would otherwise skip
    // the form entirely; (2) after this correction that test is made
    // against the stored status rather than the rejected one; (3)
    // correcting the value before BLOCK 2 disables the control avoids
    // writing to a control this script has just made inert.
    // =================================================================

    // The closed enumeration of ../choices/sys_choice_case_status.xml.
    // Used as an allowlist so a scratchpad value that is not a status
    // this application recognises is never written to the control.
    var KNOWN_STATUSES = ['Draft', 'Open', 'In Progress', 'Pending', 'Resolved', 'Closed'];

    /**
     * Reconcile the `status` control with the stored row.
     *
     * Reads g_scratchpad.x_casemgmt_stored_status, published by the
     * display Business Rule named above, and calls
     * g_form.setValue('status', <stored>) only when it can see a real
     * divergence. Silent no-op in every other case, including every
     * failure. Never throws, never clears a message, never reloads.
     */
    function restoreStoredStatus() {
        try {
            // No display rule ran (or it ran outside a form render), so
            // there is nothing authoritative to compare against.
            if (typeof g_scratchpad === 'undefined' || !g_scratchpad) {
                return;
            }

            var stored = g_scratchpad.x_casemgmt_stored_status;
            if (stored === null || stored === undefined) {
                return;
            }
            stored = String(stored).trim();

            // The display rule publishes the empty string whenever it
            // cannot prove a stored status: a new record, a row it could
            // not re-read, or an exception. That is its way of saying
            // "do nothing", and this is where it is honoured.
            if (stored === '') {
                return;
            }

            // A value outside the enumeration would mean the scratchpad
            // is not describing this application's status field. Writing
            // it would put an unrecognised value on the control, so it is
            // logged and ignored instead.
            if (KNOWN_STATUSES.indexOf(stored) === -1) {
                if (typeof jslog === 'function') {
                    jslog('x_casemgmt_case_closed_readonly_enforce: ignored an unrecognised stored ' +
                        'status from the scratchpad; the form was left untouched.');
                }
                return;
            }

            // A view may omit `status`, and a field-level ACL may remove
            // it from the form. Either way there is nothing to correct.
            if (!g_form.hasField('status')) {
                return;
            }

            var shown = g_form.getValue('status');
            shown = (shown === null || shown === undefined) ? '' : String(shown).trim();

            // The common case by far: a normal form load, where the
            // rendered value IS the stored value. Nothing happens.
            if (shown === stored) {
                return;
            }

            // The correction. The form is showing a value the database
            // does not hold - on the abort re-render, the value the
            // server has just refused - so the control is set back to
            // the stored one. setValue() is the supported API for this;
            // it updates the form's model as well as the control, so
            // BLOCK 2, the UI Policy and any later read all see the same
            // value. The status field is left flagged as modified, which
            // is the state the aborted submit had already left the form
            // in; the difference is that its value now matches the row,
            // so submitting it again is a no-op rather than a second
            // rejected transition.
            g_form.setValue('status', stored);

            // Monitoring hook: one line in the browser console naming
            // both values, so a verifier can see the correction happen
            // and confirm no message was touched.
            if (typeof jslog === 'function') {
                jslog('x_casemgmt_case_closed_readonly_enforce: the form showed status "' + shown +
                    '" while the stored row holds "' + stored + '"; the field was set back to the ' +
                    'stored value. No message was cleared and the form was not reloaded.');
            }
        } catch (restoreError) {
            // Message hygiene and value hygiene must never interfere
            // with the form: a failure here leaves everything exactly as
            // the platform rendered it.
            if (typeof jslog === 'function') {
                jslog('x_casemgmt_case_closed_readonly_enforce: could not reconcile the status field ' +
                    'with the stored row: ' + restoreError);
            }
        }
    }

    restoreStoredStatus();

    // =================================================================
    // BLOCK 2 of 2 - TERMINAL-STATE FORM LOCKDOWN. QA Issue 17, the
    // read-only half. Unchanged in behaviour by BLOCK 1 above, which
    // only ever hands it the status the database actually holds.
    // =================================================================

    // The terminal status, spelled as the Choice VALUE in
    // ../choices/sys_choice_case_status.xml.
    var TERMINAL_STATUS = 'Closed';

    // Every field the UI Policy protects, in form order. number,
    // opened_date and closed_date are absent on purpose: they are
    // unconditionally read-only in the dictionary, so the platform
    // already renders them server-side as sys_readonly.* controls.
    var FIELDS = [
        'subject',
        'type',
        'status',
        'priority',
        'description',
        'requester_name',
        'requester_email',
        'assigned_group',
        'assigned_agent',
        'pending_reason'
    ];

    // Only a Closed record is locked. On every other status this script
    // returns having changed nothing at all, leaving the form as the
    // dictionary and the field-level ACLs rendered it.
    if (g_form.getValue('status') !== TERMINAL_STATUS) {
        return;
    }

    for (var i = 0; i < FIELDS.length; i++) {
        var field = FIELDS[i];

        // A view may omit a field, and a field-level ACL may remove it
        // from the form entirely. Either way there is nothing to disable
        // and asking the platform to do it would log a client error.
        if (!g_form.hasField(field)) {
            continue;
        }

        // The supported API first. This is what closes the `description`
        // gap: called here it applies, where the equivalent UI Policy
        // action does not.
        g_form.setDisabled(field, true);

        // Then the one case the supported API cannot finish. For a
        // <select> the platform's read-only treatment sets the HTML
        // `readonly` attribute, which the specification defines as having
        // no effect on a select, so the control stays operable. Setting
        // the DOM property is what actually makes it inert. Guarded by
        // tagName so nothing else on the form is touched, and by a
        // null/undefined check because getControl() returns nothing for a
        // field the platform renders without a single addressable
        // control.
        var control = g_form.getControl(field);
        if (control && control.tagName === 'SELECT') {
            control.disabled = true;
        }
    }
}
